class Solution {
    private int result = 0;
    private int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    public int uniquePathsIII(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int sr = 0, sc = 0, empty = 1;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) { sr = i; sc = j; }
                else if (grid[i][j] == 0) empty++;
            }
        dfs(grid, sr, sc, empty, m, n);
        return result;
    }
    private void dfs(int[][] grid, int r, int c, int remaining, int m, int n) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == -1) return;
        if (grid[r][c] == 2) { if (remaining == 0) result++; return; }
        grid[r][c] = -1;
        for (int[] d : dirs) dfs(grid, r + d[0], c + d[1], remaining - 1, m, n);
        grid[r][c] = 0;
    }
}

class Solution {
    public int uniquePathsIII(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int sr = 0, sc = 0, target = 0;
        int allMask = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != -1) allMask |= (1 << (i * n + j));
                if (grid[i][j] == 1) { sr = i; sc = j; }
                if (grid[i][j] == 2) target = i * n + j;
            }
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
        return solve(sr, sc, 1 << (sr * n + sc), allMask, target, m, n, grid, dirs, memo);
    }
    private int solve(int r, int c, int mask, int allMask, int target, int m, int n, int[][] grid, int[][] dirs, java.util.Map<Long, Integer> memo) {
        int pos = r * n + c;
        if (pos == target) return mask == allMask ? 1 : 0;
        long key = ((long) mask << 20) | pos;
        if (memo.containsKey(key)) return memo.get(key);
        int count = 0;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] != -1) {
                int bit = 1 << (nr * n + nc);
                if ((mask & bit) == 0) {
                    count += solve(nr, nc, mask | bit, allMask, target, m, n, grid, dirs, memo);
                }
            }
        }
        memo.put(key, count);
        return count;
    }
}
